// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.warp(1000);
        vm.roll(10);
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback call failed");

        uint256 stored = c.pastBlockTime();
        assertTrue(stored == 1001, "pastBlockTime should be block.timestamp + 1 in reference");
    }
}
